def fade(t):
    return t * t * t * (t * (t * 6 - 15) + 10)


def perlin1d(x, gradients):
    n = len(gradients)
    if n < 2:
        raise ValueError("need at least two lattice gradients")
    if not 0 <= x <= n - 1:
        raise ValueError(f"x={x} is outside the lattice [0, {n - 1}]")
    i = int(x)
    if i == n - 1:
        i = n - 2
    t = x - i
    left = gradients[i] * t
    right = gradients[i + 1] * (t - 1.0)
    u = fade(t)
    return left + u * (right - left)


def fbm1d(x, layers, lacunarity=2.0, gain=0.5):
    if not layers:
        raise ValueError("need at least one octave")
    total = 0.0
    frequency = 1.0
    amplitude = 1.0
    for gradients in layers:
        total += amplitude * perlin1d(x * frequency, gradients)
        frequency *= lacunarity
        amplitude *= gain
    return total
